const run_id = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : (r & 0x3 | 0x8);
  return v.toString(16);
});

return [{
  json: {
    run_id,
    run_date: new Date().toISOString().split('T')[0],
    trigger_source: 'gdrive'
  }
}];

const items = $input.all();
if (items.length === 0) return [];

const runId = $('Set Poll Run Vars').first().json.run_id;
const ordinalMap = {};
const results = [];

for (const item of items) {
  const raw = item.json;
  const bank_account_code = (raw.BankAccountCode || raw.bank_account_code || raw.Account || '').toString().trim();
  const txn_date_raw = raw.Date || raw.TransactionDate || raw.txn_date || '';
  const txn_date = txn_date_raw.includes('/')
    ? txn_date_raw.split('/').reverse().join('-')
    : txn_date_raw.split('T')[0];

  const rawAmount = parseFloat(raw.Amount || raw.amount || '0');
  const direction = rawAmount < 0
    || (raw.Type || '').toLowerCase() === 'debit'
    || (raw.Direction || '').toLowerCase() === 'money_out'
    ? 'money_out' : 'money_in';
  const amount_minor_units = Math.round(Math.abs(rawAmount) * 100);

  const reference_text = (raw.Reference || raw.reference_text || raw.Ref || '').toString().trim() || null;
  const description_text = (raw.Description || raw.description_text || raw.Memo || '').toString().trim() || null;
  const counterparty_text = (raw.Counterparty || raw.counterparty_text || raw.Payee || raw.Payer || '').toString().trim() || null;
  const currency_code = (raw.Currency || raw.currency_code || 'USD').toString().trim().toUpperCase();

  const ordKey = [bank_account_code, txn_date, amount_minor_units, direction, reference_text || ''].join('|');
  ordinalMap[ordKey] = (ordinalMap[ordKey] || 0) + 1;
  const ordinal = ordinalMap[ordKey];

  results.push({
    json: {
      bank_account_code,
      txn_date,
      amount_minor_units,
      direction,
      reference_text,
      description_text,
      counterparty_text,
      currency_code,
      ordinal,
      source: 'csv',
      ingest_run_id: runId,
      raw_payload: raw
    }
  });
}

return results;

