// Xero webhook verification (structural, test-environment).
//
// IMPORTANT: True cryptographic HMAC verification is DEFERRED. The n8n Webhook
// node on this plan does not reliably preserve the byte-exact raw payload Xero
// signed, and the Code-node sandbox blocks require('crypto'). Until raw body
// access is available at deployment, this node performs STRUCTURAL
// verification: x-xero-signature header present and well-formed (base64
// SHA256 shape), and body is a valid Xero webhook envelope. This proves the
// control point is wired; it is NOT a substitute for HMAC in production.
//
// TODO(production): restore HMAC via the n8n Crypto node over the raw body
// against the webhook signing key. Rotate the signing key before client use.

const webhookData = $('Xero Webhook').first().json;
const headers = webhookData.headers || {};

let body = webhookData.body || {};
if (typeof body === 'string') {
  try { body = JSON.parse(body); }
  catch (e) { return [{ json: { verified: false, reason: 'unparseable_body' } }]; }
}

const sigHeader = headers['x-xero-signature'] || headers['X-Xero-Signature'];

if (!sigHeader) {
  return [{ json: { verified: false, reason: 'missing_signature_header' } }];
}
if (!/^[A-Za-z0-9+/]{43}=$/.test(sigHeader)) {
  return [{ json: { verified: false, reason: 'malformed_signature_header' } }];
}

const hasEvents = Array.isArray(body.events);
const hasSequences = typeof body.firstEventSequence === 'number'
                  && typeof body.lastEventSequence === 'number';
const hasEntropy = typeof body.entropy === 'string';

if (!hasEvents || !hasSequences || !hasEntropy) {
  return [{ json: { verified: false, reason: 'malformed_xero_envelope' } }];
}

return [{ json: { verified: true, payload: body } }];

const payload = $json.payload;

const ALLOWED_CATEGORIES = ['INVOICE', 'CONTACT', 'CREDITNOTE'];

const events = (payload.events || []).filter(e =>
  ALLOWED_CATEGORIES.includes(e.category) || ALLOWED_CATEGORIES.includes(e.eventCategory)
);

if (events.length === 0) return [];

const run_id = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : (r & 0x3 | 0x8);
  return v.toString(16);
});

return [{
  json: {
    run_id,
    run_date: new Date().toISOString().split('T')[0],
    trigger_source: 'webhook',
    event_count: events.length,
    events: events
  }
}];

const line = $('Split In Batches').first().json;
const xeroResponse = $input.first().json;
const invoices = xeroResponse.Invoices || [];
const config = line.config || {};

// Config keys aligned with bank_recon.config schema
const tolPct = parseFloat(config.tolerance_percentage);
const tolAbs = parseFloat(config.tolerance_absolute_minor);
const dateWindowDays = parseInt(config.date_window_days, 10);
const threshold = parseFloat(config.autoclear_threshold);
const refWeight = parseFloat(config.weight_reference);
const contactWeight = parseFloat(config.weight_contact);

const lineDate = new Date(line.txn_date);
const lineAmount = parseInt(line.amount_minor_units, 10);

let bestMatch = null;
let bestScore = 0;

for (const inv of invoices) {
  // Direction gate
  const invDir = inv.Type === 'ACCREC' ? 'money_in' : 'money_out';
  if (invDir !== line.direction) continue;

  // Amount gate: abs(diff) <= max(absolute floor, percentage of line amount)
  const invAmount = Math.round(parseFloat(inv.AmountDue || inv.Total || '0') * 100);
  const amtDiff = Math.abs(invAmount - lineAmount);
  const maxAmtDiff = Math.max(tolAbs, lineAmount * tolPct);
  if (amtDiff > maxAmtDiff) continue;

  // Date gate: payment must fall within the invoice's lifecycle.
  // Valid range: (issue date minus window) to (due date plus window).
  const invIssueDate = new Date(inv.DateString || inv.Date);
  const invDueDate = new Date(inv.DueDateString || inv.DueDate || inv.DateString);
  const earliestValid = new Date(invIssueDate.getTime() - dateWindowDays * 86400000);
  const latestValid = new Date(invDueDate.getTime() + dateWindowDays * 86400000);
  if (lineDate < earliestValid || lineDate > latestValid) continue;

  const daysFromDue = Math.round((lineDate - invDueDate) / 86400000);

  // Reference score
  let refScore = 0;
  if (line.reference_text && inv.InvoiceNumber) {
    const ref = line.reference_text.toLowerCase();
    const num = inv.InvoiceNumber.toLowerCase();
    if (ref.includes(num) || num.includes(ref)) {
      refScore = 1.0;
    } else {
      const shorter = ref.length < num.length ? ref : num;
      const longer = ref.length >= num.length ? ref : num;
      if (longer.includes(shorter)) refScore = shorter.length / longer.length;
    }
  }

  // Contact score
  let contactScore = 0;
  if (line.counterparty_text && inv.Contact && inv.Contact.Name) {
    const cp = line.counterparty_text.toLowerCase();
    const cn = inv.Contact.Name.toLowerCase();
    if (cp === cn) contactScore = 1.0;
    else if (cp.includes(cn) || cn.includes(cp)) contactScore = 0.7;
  }

  const score = (refScore * refWeight) + (contactScore * contactWeight);

  if (score > bestScore) {
    bestScore = score;
    bestMatch = {
      xero_document_id: inv.InvoiceID,
      xero_document_type: inv.Type === 'ACCREC' ? 'invoice' : 'bill',
      xero_document_number: inv.InvoiceNumber,
      xero_contact_name: inv.Contact ? inv.Contact.Name : null,
      xero_amount_due: invAmount,
      match_score: Math.round(score * 100) / 100,
      amount_diff_minor: amtDiff,
      days_from_due: daysFromDue
    };
  }
}

return [{
  json: {
    ...line,
    v1_matched: bestMatch !== null && bestScore >= threshold,
    v1_match: bestMatch,
    v1_best_score: Math.round(bestScore * 100) / 100
  }
}];

const line = $('Evaluate Match').first().json;
const rules = $input.all().map(r => r.json);

if (!rules.length || !rules[0].id) {
  return [{ json: { ...line, rule_hit: false, rule_match: null } }];
}

for (const rule of rules) {
  if (rule.direction && rule.direction !== line.direction) continue;
  if (rule.amount_min_minor && line.amount_minor_units < rule.amount_min_minor) continue;
  if (rule.amount_max_minor && line.amount_minor_units > rule.amount_max_minor) continue;

  if (rule.vendor_pattern) {
    const counterparty = (line.counterparty_text || '').toLowerCase();
    if (!counterparty.includes(rule.vendor_pattern.toLowerCase())) continue;
  }

  if (rule.description_pattern) {
    const descText = [line.description_text || '', line.reference_text || ''].join(' ').toLowerCase();
    if (!descText.includes(rule.description_pattern.toLowerCase())) continue;
  }

  return [{
    json: {
      ...line,
      rule_hit: true,
      rule_match: {
        rule_id: rule.id,
        account_code: rule.account_code,
        confidence: 1.0,
        explanation: 'Matched rule ' + rule.id + ' (vendor: ' + (rule.vendor_pattern || 'any') + ', description: ' + (rule.description_pattern || 'any') + ')'
      }
    }
  }];
}

return [{ json: { ...line, rule_hit: false, rule_match: null } }];

