const line = $('Split In Batches').item.json;
const result = $input.first().json.message?.content ?? $input.first().json;

const threshold = parseFloat(line.config.categorisation_threshold);
const confident = (result.confidence ?? 0) >= threshold;

return [{
  json: {
    ...line,
    classify_hit: confident,
    classify_match: confident ? {
      account_code: result.account_code,
      account_name: result.account_name,
      confidence: result.confidence,
      reasoning: result.reasoning
    } : null
  }
}];
